fn id(v: &Value) -> bool { text(v,64) && v.as_str().is_some_and(|s| !matches!(s,"."|"..") && !s.chars().any(char::is_control)) }
fn iso(v: &Value) -> bool { v.as_str().is_some_and(|s| rentemester_engine::company_knowledge::iso(s).is_ok()) }
