    v["roles"].as_array().is_some_and(|a|a.iter().all(|r|r["companySlug"].is_string() && r["role"].is_string() && r["defaults"].is_object())) &&
    v["aliases"].as_array().is_some_and(|a|a.iter().all(|r|r["alias"].is_string() && r["source"].is_string() && r["review_state"].is_string() && r.get("observed_at").is_some_and(|v|v.is_null()||iso(v)) && r.get("payload_hash").is_some_and(|v|v.is_null()||hash(v)))) &&
    v["assertions"].as_array().is_some_and(|a|a.iter().all(|r|["field","value","source","review_state"].iter().all(|k|r[k].is_string()) && iso(&r["observed_at"]) && hash(&r["payload_hash"])))
