// Canonical RFC4648 spelling and the original storage bound; never rewrite bytes.
fn original(v: &Value) -> bool {
    let Some(s)=v.as_str() else { return false; };
    if s.is_empty() || s.len()>22_369_624 || s.len()%4!=0 { return false; }
    let table=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut decoded=0;
    for (i,c) in s.as_bytes().chunks_exact(4).enumerate() {
        let last=(i+1)*4==s.len();
        let Some(a)=table.iter().position(|b|*b==c[0]) else{return false};
        let Some(b)=table.iter().position(|b|*b==c[1]) else{return false};
        let _=a;
        if c[2]==b'=' { if !last || c[3]!=b'=' || b%16!=0 { return false; } decoded+=1; }
        else { let Some(d)=table.iter().position(|b|*b==c[2]) else{return false};
            if c[3]==b'=' { if !last || d%4!=0 {return false;} decoded+=2; }
            else { if !table.contains(&c[3]) {return false;} decoded+=3; }
        }
    }
    decoded<=16*1024*1024
}
